    "a": "因为他动的是规则，不是人事。卖官价目一废，吏部考课重新有效；李春芳、张居正、殷正茂这批人被起用，才有了后来的隆庆开海与万历新政。首辅任期长短不重要，重要的是他把「谁能做官」的标准从钱改回了资历与才干。",
