    "匪首们以为糊弄过去了，放松了戒备。",
    "数日之后，他突然发难，逮捕并处死其中数人。",
    "被杀的几个人，都是曾受朝廷招安又复叛的老匪。",
    "其余胁从者被遣散归农，不再追究。",
    "赣南的匪患由此真正收尾，但「诱杀」也成了他名声上的一笔。",
    "被杀者的部众被编入乡兵，山寨拆毁，路终于通了。"
