    "地方士绅认可他的果决，士林则有人非议其诈。",
    "这套「先安后杀」的做法，他在平宁王时又用过一次。",
    "赣南从此安静，但「诱杀」二字一直跟着他。",
    "被杀者的名字被记在案卷里，后来成了他「杀降」的证据。"
