    "text": "土匪们看到王大人以礼相待，都十分高兴，以为糊弄过去了，可是没过两天，王大人突然发难，杀掉了其中几个人，而这几个人都是曾经受过朝廷招安的，这种老痞子，王守仁是不感兴趣的。",
    "proves": "先以礼招安，两天后突然发难，杀掉曾受招安的匪首",
