    "王守仁的杂牌军由此从被动转为主动。",
    "朝廷尚未发兵，平叛的胜负已定在江西一隅。",
    "他用假文书换来的十余日，是这场战争真正的转折。",
    "他后来回忆，最险的一步不是攻城，是让宁王相信那些假文书。"
