    "袁崇焕到任后，多次要求毛文龙受节制，均被推脱。",
    "崇祯二年六月，袁崇焕亲赴皮岛，当众列其十二大罪。",
    "他取出尚方剑，将毛文龙斩于帐下，全军震慑。",
    "事后上疏请罪，崇祯虽然不满，却只能认可。",
    "皮岛群龙无首，牵制后金的作用大打折扣。",
