    "王振的强硬，让也先找到了动员诸部的理由。",
    "明朝把外交当成买卖，也先把买卖当成开战的本钱。",
    "边境的火药，从马价开始堆积。",
    "此后朝贡不再是羁縻的手段，而成了双方较劲的战场。"
