    "a": "因为朝贡在瓦剌眼里不是礼节，是生意。也先靠贡使获利，王振压低马价、罚没货物，等于断了他的财路。他没有能力逼明朝赔钱，就用武力讨；「减价」只是借口，真正的账是血本无归。明朝这边把外交当恩赐，也先把外交当买卖，理解错位，战争就来了。",
