    "奏疏虽被压下，却让更多人看清魏忠贤。",
    "东林与阉党的对峙，进入白热化。",
    "魏忠贤知道，光靠皇帝挡不住天下人的嘴。",
    "他开始筹划用一场大狱，把写文章的人一起除掉。",
    "他从此把杨涟的名字写在第一等的清除名单上。"
