    "东林的清白，被一纸伪供抹黑。",
    "汪文言的贪，成了整个东林的软肋。",
    "兴狱成了魏忠贤清除政敌的标准手段。",
    "从此以后，杀人不靠罪证，靠口供。",
    "有了这份口供，抓人就不必再讲罪名是否成立。"
