  "era": "嘉靖二年",
  "title": "上疏争皇考：一句话替皇帝说破",
  "tag": "押注",
  "hero": false,
  "before": {
   "lead": "满朝都在争皇帝该认谁当爹，他递上了一篇最直白的文章。",
   "layers": [
    "结构条件：嘉靖以藩王入继大统，为尊崇生父与杨廷和为首的群臣对峙；大礼议僵持不下。",
    "近端触发：嘉靖二年十一月，张璁上疏为皇帝争皇考，只讲一个意思：皇帝想认谁当爹都行。",
    "决策者动机：他要借议礼翻身；嘉靖要一个替他说破的人。"
   ]
  },
  "course": {
   "lead": "引经据典一大篇，核心只有一句。",
   "beats": [
    "嘉靖二年（1523）十一月，张璁上疏。",
    "这篇文书引经据典、旁征博引。",
    "内容其实很枯燥，只向朱厚熜说明一个观点。",
    "你想认谁当爹都行。",
    "矛头直指首辅杨廷和。",
    "嘉靖大喜，终于有人替他把话说明白了。",
    "一个六品主事，从此进入皇帝的视线。",
    "他把历代礼制一条条抄出，证明「继统」不必「继嗣」。",
    "奏章递上去的那天，他把自己的仕途全押在了这一篇上。"
   ]
  },
  "after": {
   "lead": "一篇文章，把他从刑部推到了风口。",
   "chains": [
    "杨廷和一党从此把他视为眼中钉。",
    "嘉靖把他当成可以倚重的自己人。",
    "他押对了皇帝的心思，也押上了全部前程。",
    "大礼议从此有了一个能写、能辩的急先锋。",
    "朝中的清流，开始把他叫作「议礼小人」。",
    "杨廷和看到奏章后，立刻意识到这不是一个六品主事能写出的东西。"
   ]
  },
  "why": [
   {
    "q": "为什么张璁敢公开和首辅杨廷和作对？",
    "a": "因为他已经没有什么可失去的：六品主事、四十七八岁，正常升迁无望。而皇帝正被群臣压得难受，缺一个能引经据典替他说「可以」的人。张璁看准了这个缺口，用一篇文章把前程押上去。赌赢了就是一步登天，赌输了也不过是丢官。",
    "basis": {
     "type": "book",
     "text": "《明朝那些事儿》第一章 皇帝很脆弱"
    }
   }
  ],
  "quotes": [
   {
    "text": "这篇文书的内容就不介绍了，这是一篇比较枯燥的文章，估计大家也没有兴趣读，在文中，张璁引经据典，旁征博引，只向朱厚熜说明了一个观点——你想认谁当爹都行。",
    "proves": "张璁上疏引经据典，只向皇帝说明：你想认谁当爹都行",
    "source": {
     "vol": "肆 粉饰太平",
     "volName": "",
     "chapter": "第一章 皇帝很脆弱",
     "index": 87,
     "book": "明朝那些事儿"
    }
   }
  ],
