    "英宗居南宫，兄弟之间的猜忌越积越深。",
    "于谦夹在景泰帝与太上皇之间，两头不讨好。",
    "他拒绝荫子，家人也没有因他得势。",
    "这份不争，后来被政敌说成「专权」。",
    "景泰帝把兄长安置在南宫，门禁森严，兄弟之间的裂痕越来越深。"
