    "焦芳入阁，内阁从此成了他意志的传声筒。",
    "张彩替他打理章奏，整人的名单越列越长。",
    "文官集团被分化，清流与附逆者的界限模糊。",
    "这个集团后来在倒台时被一并清算。",
    "宦官与文官合流，是正德朝政治最坏的一种形态。"
