    "a": "因为道德与公理，只有在实力相等的情况下才能拿出来讨论。徐海把同党交了、戒备散了，实力先没了，所以只能死；汪直手里还有船与众，还有议价的余地。胡宗宪的计能杀人，也能留人，看的是对方还剩多少本钱。",
