    "text": "陈友谅军大为慌乱，万不料朱元璋军竟然主动发起进攻，急忙派出舰队迎击，此时，徐达的舰队突然分成十一队，从不同角度围攻巨舰（类似群狼战术），由于巨舰行动不便，顾此失彼，无法打退徐达的攻击，而徐达军乘势攀上其中一条巨舰，杀敌一千余人，并俘获该舰，陈友谅前军被打败。",
    "proves": "徐达舰队分十一队围攻巨舰，杀敌千余并俘获该舰，陈友谅前军败",
