    "朱瞻圻的潜伏，后来也成了朝廷追究的把柄。",
    "宗室刺探京师的举动，加深了皇帝的猜忌。，宣宗对这位叔父多了戒心",
    "这套办法说明，他已在做最坏的打算。",
    "永乐末年的继承危机，就此埋下引线。"
