    "a": "因为他在乐安，离皇帝和朝臣都远，一旦京中发生变故，晚一步就什么都赶不上。派朱瞻圻常驻京城，用快马连夜传信，等于给自己装了一双眼睛。这套安排不是未雨绸缪，是在为抢位做准备；只是消息再快，也快不过朝廷的部署。",
