    "侯泰奉皇帝之命前来。，名义上是宣慰",
    "迎接他的，是气焰嚣张的朱高煦。",
    "这位造反兄傲气十足。，自恃是叔父辈",
    "他竟然面对天子来使南面而坐。，不给来使留一点体面",
