    "a": "因为夺门是合伙的买卖，分赃却只能有一个主家。徐有贞入阁掌都察院，又有谋主之名，是他独揽朝政的最大障碍。用言官弹劾、天天到皇帝面前闹，是把公器当私斗的工具。同伙可以共患难，不能共富贵。",
