    "q": "为什么移宫要靠一整天游说，而不是一道奏疏？",
    "a": "因为移宫不是法律问题，是人心问题：百官若不肯一起站出来，内廷就有理由拖着；奏疏可以压，人心压不住。杨涟一天跑遍内阁与各部，是把分散的顾虑一个个拆掉。他也因此得罪了李选侍一党，代价在几年后由诏狱来收。",
