    "左光斗只比他多活一天，同一个牢里，前后脚。",
    "魏大中、袁化中、周朝瑞相继遇害。",
    "顾大章最后也没有活下来。",
    "至此，杨涟、左光斗、魏大中、袁化中、周朝瑞、顾大章六人全部遇害。",
    "此案史称「六君子之狱」。",
    "六个人都不肯在一份假口供上画押，宁可挨刑。",
    "他们的罪名，是收受贿赂、结交内臣，没有一条拿得出实证。"
