    "团营是武宗亲手组建的，由江彬操纵，边兵骄横难制。",
    "杨廷和很快发布了命令，一道接一道，不留空档。",
    "解散团营，解除江彬手中的武装，把人先架空。",
    "再由张永、郭勋等人控制京城防务，把城门钥匙换手。",
    "并且严禁任何军队调动，违者以军法论处。",
    "江彬手里没了兵，也就没了说话的底气，只能听候处置。",
    "这一串命令，都在新君到京之前办完，没有流一滴血。"
