    "皇帝要追尊自己的生父，把本支的名分抬到最上面。",
    "杨廷和坚持继统即继嗣：继了皇位，就得继这一支的嗣。",
    "按明代规定，首辅认为皇帝的意见不对，可以把圣旨退回去。",
    "这种权力的名字，叫封驳，是内阁压箱底的本钱。",
    "于是所谓圣旨，竟然被他退了回来，原样送回宫中。",
    "一边是少年天子，一边是三朝老臣，都不肯先低头。",
    "谁也不肯先退这一步，朝堂上的气氛一日比一日紧。"
