    "京畿的防务连成了一片。",
    "辽东军打出了士气。",
    "孙承宗的调度再次被人认可。",
    "他因此多了一份继续用兵的底气。",
    "大凌河那边的麻烦，还在后头等着。",
    "他入城时只带随从数人，家眷留在城外，以示与城共存亡。"
