    "胡宗宪的处境更尴尬：既不能杀，也不能放。",
    "朝廷里弹劾的风声已经起来，收留海商成了罪状。",
    "杭州的这一趟，成了他一生的转折。",
    "海上的部众失去主心骨，只能各自观望。",
