    "近端触发：仁宗即位，擢杨士奇为礼部侍郎兼大学士，五品小官一下成了三品；宣德五年，于谦被越级提拔，众人不服，杨士奇出面称他是难遇奇才。",
    "决策者动机：仁宗要报东宫旧恩、也要有人替他撑起内阁；杨士奇要为朝廷留住人才，也深知非科举出身者被人轻视的滋味。"
