    "近端触发：英宗即位，七十一岁的杨士奇仍居首辅；正统五年杨荣去世，三杨只剩杨士奇与杨溥，皆年老多病。",
    "决策者动机：他要维持内阁的体面与旧制，让幼主在位时政事不乱；王振要借皇帝的信任扩张司礼监的权。"
