    "近端触发：万历四十三年（1615），李成梁去世；次年，努尔哈赤在赫图阿拉建立政权，年号天命，史称后金。",
    "决策者动机：努尔哈赤不愿在老上司生前撕破脸；李成梁一死，他便无所顾忌。"
