    "他在辽东经营了四十余年，门生故吏遍布边镇。",
    "此时努尔哈赤已统一建州，兵强马壮，只差一个名号。",
    "但努尔哈赤没有立刻称汗，把事情压着没有办。",
    "几个月后，到了万历四十四年（1616）。",
