    "text": "但李如松不知道的是，几乎与此同时，那个曾经教过他的老先生，正躺在一所破屋之中，他已经卖光了所有的字画，贫病交加，且无人理会。不久之后，他带着满腔的悲愤静悄悄地离开了人世，年七十三。",
